import{_ as a,o as s,c as t,aj as i}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"App shell pattern","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"ecosystem/service-workers/app-shell.md","filePath":"ecosystem/service-workers/app-shell.md"}'),p={name:"ecosystem/service-workers/app-shell.md"};function n(l,e,o,h,r,c){return s(),t("div",null,e[0]||(e[0]=[i(`<h1 id="app-shell-pattern" tabindex="-1">App shell pattern <a class="header-anchor" href="#app-shell-pattern" aria-label="Permalink to &quot;App shell pattern&quot;">​</a></h1><p>The <a href="https://developer.chrome.com/blog/app-shell" target="_blank" rel="noreferrer">App shell pattern</a> is a way to render a portion of your application using a route at build time. It can improve the user experience by quickly launching a static rendered page (a skeleton common to all pages) while the browser downloads the full client version and switches to it automatically after the code loads.</p><p>This gives users a meaningful first paint of your application that appears quickly because the browser can render the HTML and CSS without the need to initialize any JavaScript.</p><h3 id="_1-prepare-the-application" tabindex="-1">1. Prepare the application <a class="header-anchor" href="#_1-prepare-the-application" aria-label="Permalink to &quot;1. Prepare the application&quot;">​</a></h3><p>Do this with the following Angular CLI command:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>For an existing application, you have to manually add the <code>Router</code> and defining a <code>&lt;router-outlet&gt;</code> within your application.</p><h3 id="_2-create-the-application-shell" tabindex="-1">2. Create the application shell <a class="header-anchor" href="#_2-create-the-application-shell" aria-label="Permalink to &quot;2. Create the application shell&quot;">​</a></h3><p>Use the Angular CLI to automatically create the application shell.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-shell</span></span></code></pre></div><p>For more information about this command, see <a href="https://angular.dev/cli/generate/app-shell" target="_blank" rel="noreferrer">App shell command</a>.</p><p>The command updates the application code and adds extra files to the project structure.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src</span></span>
<span class="line"><span>├── app</span></span>
<span class="line"><span>│ ├── app.config.server.ts # server application configuration</span></span>
<span class="line"><span>│ ├── app.routes.server.ts # server routes configuration</span></span>
<span class="line"><span>│ └── app-shell # app-shell component</span></span>
<span class="line"><span>│   ├── app-shell.css</span></span>
<span class="line"><span>│   ├── app-shell.html</span></span>
<span class="line"><span>│   ├── app-shell.spec.ts</span></span>
<span class="line"><span>│   └── app-shell.ts</span></span>
<span class="line"><span>└── main.server.ts # main server application bootstrapping</span></span></code></pre></div><h3 id="_3-verify-the-application-is-built-with-the-shell-content" tabindex="-1">3. Verify the application is built with the shell content <a class="header-anchor" href="#_3-verify-the-application-is-built-with-the-shell-content" aria-label="Permalink to &quot;3. Verify the application is built with the shell content&quot;">​</a></h3><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --configuration=development</span></span></code></pre></div><p>Or to use the production configuration.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>To verify the build output, open <code class="no-auto-link">dist/my-app/browser/index.html</code>. Look for default text <code>app-shell works!</code> to show that the application shell route was rendered as part of the output.</p>`,18)]))}const g=a(p,[["render",n]]);export{u as __pageData,g as default};
